@pytest.mark.evidence(condition_ref="TC-01", story_ref="S01")
def test_01_create_account(page: Page, evidence_tracker):
    evidence_tracker.navigate('http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.click('#accountNext', label='Create Account', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.fill('#email', 'customer@example.com', label='email', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.fill('#password', 'SecurePass123', label='password', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.fill('#firstName', 'John', label='First Name', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.fill('#lastName', 'Doe', label='Last Name', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.fill('#dob', '1990-01-01', label='Date of Birth', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.fill('#addressLine1', '123 Main St', label='Address', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.click('#quoteSubmit', label='Submit', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')
    evidence_tracker.assert_visible('#page-account', label='account created', expected_page='http://localhost:8781/generated_tests/mock_insurance_site.html')


